{
  "cases": [
    {
      "title": "UX: Restricción funcional para rol pending",
      "preconditions": [
        "El usuario tiene el rol `pending`.",
        "Es nuevo y no ha solicitado acceso manualmente."
      ],
      "steps": [
        "Intento acceder al chat del sistema.",
        "Seleccionar una opción de chat o intentar iniciar conversación."
      ],
      "expected": "La funcionalidad de chat debe aparecer deshabilitada o mostrar un mensaje indicando que el acceso requiere aprobación pendiente. No se debe permitir la ejecución real de la tarea de mensajería.",
      "evidence": [
        {
          "passage_id": "Pbef6e2a6f4a41e236e72a901",
          "quote": "\"Solo puede ver la pantalla de espera; no puede usar el chat\""
        }
      ]
    },
    {
      "title": "UX: Liberación de accesos al cambiar rol a user",
      "preconditions": [
        "El usuario tiene inicialmente el rol `pending`.",
        "Se ha completado la operación de cambio de rol a `user` mediante un administrador."
      ],
      "steps": [
        "Esperar que el estado del sistema se actualice tras el cambio de rol.",
        "Intento acceder al chat nuevamente."
      ],
      "expected": "La funcionalidad de chat debe habilitarse completamente, permitiendo interacciones normales.",
      "evidence": [
        {
          "passage_id": "Pbef6e2a6f4a41e236e72a901",
          "quote": "\"El usuario `user`... Chat\""
        },
        {
          "passage_id": "Pbef6e2a6f4a41e236e72a901",
          "quote": "\"Un admin debe cambiar el rol a `user` para habilitar el acceso.\""
        }
      ]
    },
    {
      "title": "Pregunta abierta: Comportamiento de la UI frente al cambio de rol no solicitado por el usuario",
      "preconditions": [
        "Se tiene conocimiento de que un admin puede cambiar el rol sin notificación explícita del usuario.",
        "Se observa una discrepancia potencial en el comportamiento UI."
      ],
      "steps": [
        "Identificar si existe una notificación visual al cambio de rol pendiente a user."
      ],
      "expected": "Definir los requisitos sobre la comunicación de cambios de estado al usuario final.",
      "evidence": [
        {
          "passage_id": "Pbef6e2a6f4a41e236e72a901",
          "quote": "\"Un admin debe cambiar el rol a `user` para habilitar el acceso.\""
        },
        {
          "passage_id": "Pbef6e2a6f4a41e236e72a901",
          "quote": "\"Los usuarios `user` ven estas tabs pero no pueden acceder a su contenido.\""
        }
      ]
    }
  ],"open_questions": [
    "¿Debería el usuario recibir una notificación explícita cuando un admin cambia su rol de pending a user?"
  ]}
